/**
 * Unit tests for ReaderBasedJsonParser.nextToken()
 * Aiming for high branch and line coverage.
 */
public class ReaderBasedJsonParser_nextToken_TriageGen1Test {

    private JsonToken parseTokens(String json) throws IOException {
        // Using the standard way to instantiate via JsonFactory is safer, 
        // but since the prompt specifies the constructor, we simulate the logic.
        // In a real Jackson environment, one would use JsonFactory.
        com.fasterxml.jackson.core.JsonFactory factory = new com.fasterxml.jackson.core.JsonFactory();
        JsonParser parser = factory.createParser(new StringReader(json));

        // We will collect tokens to verify the sequence
        return null; 
    }

    // Helper to execute the test logic via a factory to ensure internal state (parsingContext, etc.) is valid
    private void assertTokenSequence(String json, JsonToken... expectedTokens) throws IOException {
        com.fasterxml.jackson.core.JsonFactory factory = new com.fasterxml.jackson.core.JsonFactory();
        JsonParser parser = factory.createParser(new StringReader(json));

        for (JsonToken expected : expectedTokens) {
            JsonToken actual = parser.nextToken();
            assertEquals("Token mismatch. Expected: " + expected + " but got: " + actual, expected, actual);
        }

        // Ensure no more tokens if we expected EOF
        if (expectedTokens.length > 0 && expectedTokens[expectedTokens.length - 1] != JsonToken.NOT_AVAILABLE) {
             // This is a simplified check
        }
    }

    @Test
    public void testNextToken_BasicTypes() throws IOException {
        com.fasterxml.jackson.core.JsonFactory factory = new com.fasterxml.jackson.core.JsonFactory();

        // Test String
        JsonParser p1 = factory.createParser(new StringReader("\"hello\""));
        assertEquals(JsonToken.VALUE_STRING, p1.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, p1.nextToken());

        // Test Number (Positive)
        JsonParser p2 = factory.createParser(new StringReader("123"));
        assertEquals(JsonToken.VALUE_NUMBER_INT, p2.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, p2.nextToken());

        // Test Number (Negative)
        JsonParser p3 = factory.createParser(new StringReader("-456"));
        assertEquals(JsonToken.VALUE_NUMBER_INT, p3.nextToken());

        // Test Boolean True
        JsonParser p4 = factory.createParser(new StringReader("true"));
        assertEquals(JsonToken.VALUE_TRUE, p4.nextToken());

        // Test Boolean False
        JsonParser p5 = factory.createParser(new StringReader("false"));
        assertEquals(JsonToken.VALUE_FALSE, p5.nextToken());

        // Test Null
        JsonParser p6 = factory.createParser(new StringReader("null"));
        assertEquals(JsonToken.VALUE_NULL, p6.nextToken());
    }

    @Test
    public void testNextToken_Structural() throws IOException {
        com.fasterxml.jackson.core.JsonFactory factory = new com.fasterxml.jackson.core.JsonFactory();

        // Test Array
        JsonParser p1 = factory.createParser(new StringReader("[1, 2]"));
        assertEquals(JsonToken.START_ARRAY, p1.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, p1.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, p1.nextToken());
        assertEquals(JsonToken.END_ARRAY, p1.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, p1.nextToken());

        // Test Object and Field Name logic (the _nextAfterName branch)
        JsonParser p2 = factory.createParser(new StringReader("{\"key\":\"val\"}"));
        assertEquals(JsonToken.START_OBJECT, p2.nextToken());
        assertEquals(JsonToken.FIELD_NAME, p2.nextToken()); // This tests the logic where _currToken is FIELD_NAME
        assertEquals(JsonToken.VALUE_STRING, p2.nextToken()); // Tests _nextAfterName() returning the value
        assertEquals(JsonToken.END_OBJECT, p2.nextToken());
    }

    @Test
    public void testNextToken_NestedStructures() throws IOException {
        com.fasterxml.jackson.core.JsonFactory factory = new com.fasterxml.jackson.core.JsonFactory();
        String json = "{\"a\": [1, {\"b\": true}]}";
        JsonParser p = factory.createParser(new StringReader(json));

        assertEquals(JsonToken.START_OBJECT, p.nextToken());
        assertEquals(JsonToken.FIELD_NAME, p.nextToken());
        assertEquals(JsonToken.START_ARRAY, p.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, p.nextToken());
        assertEquals(JsonToken.END_ARRAY, p.nextToken()); // This might depend on if comma is skipped
        // The logic in the provided code handles commas and context switches.
    }

    @Test(expected = IOException.class)
    public void testNextToken_MismatchedEndArray() throws IOException {
        com.fasterxml.jackson.core.JsonFactory factory = new com.fasterxml.jackson.core.JsonFactory();
        // Providing a closing bracket where an object is expected or vice versa
        // to trigger _reportMismatchedEndMarker
        JsonParser p = factory.createParser(new StringReader("]"));
        p.nextToken();
    }

    @Test(expected = IOException.class)
    public void testNextToken_MismatchedEndObject() throws IOException {
        com.fasterxml.jackson.core.JsonFactory factory = new com.fasterxml.jackson.core.JsonFactory();
        JsonParser p = factory.createParser(new StringReader("}"));
        p.nextToken();
    }

    @Test(expected = IOException.class)
    public void testNextToken_UnexpectedChar() throws IOException {
        com.fasterxml.jackson.core.JsonFactory factory = new com.fasterxml.jackson.core.JsonFactory();
        // A closing brace in a place where a value is expected
        JsonParser p = factory.createParser(new StringReader("[}"));
        p.nextToken(); // START_ARRAY
        p.nextToken(); // Should hit _reportUnexpectedChar
    }

    @Test
    public void testNextToken_EndOfInput() throws IOException {
        com.fasterxml.jackson.core.JsonFactory factory = new com.fasterxml.jackson.core.JsonFactory();
        JsonParser p = factory.createParser(new StringReader(""));
        // i < 0 branch
        assertNull(p.nextToken());
    }

    @Test
    public void testNextToken_WhitespaceAndCommas() throws IOException {
        com.fasterxml.jackson.core.JsonFactory factory = new com.fasterxml.jackson.core.JsonFactory();
        // Testing _skipWSOrEnd and _skipComma
        String json = "  [  1  ,   2  ]  ";
        JsonParser p = factory.createParser(new StringReader(json));

        assertEquals(JsonToken.START_ARRAY, p.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, p.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, p.nextToken());
        assertEquals(JsonToken.END_ARRAY, p.nextToken());
    }

    @Test
    public void testNextToken_FieldAfterNameBranch() throws IOException {
        com.fasterxml.jackson.core.JsonFactory factory = new com.fasterxml.jackson.core.JsonFactory();
        // This tests the specific branch: if (_currToken == JsonToken.FIELD_NAME) return _nextAfterName();
        // In Jackson, once nextToken() returns FIELD_NAME, the next call to nextToken() 
        // automatically enters the _nextAfterName() logic.
        JsonParser p = factory.createParser(new StringReader("{\"a\":1}"));
        p.nextToken(); // START_OBJECT
        p.nextToken(); // FIELD_NAME ("a")
        assertEquals(JsonToken.VALUE_NUMBER_INT, p.nextToken()); // Should return 1 via _nextAfterName
    }
}
